package com.inkproof;

import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Color;import java.util.concurrent.*;import java.net.*;import java.io.*;

public final class MainActivity extends Activity {
    private Notebook notebook;private LinearLayout pages,root,toolbar;private InkView selected;private String tool="pen";private int color=0xff182433;private float width=3;private int stabilization=2;private final ScheduledExecutorService disk=Executors.newSingleThreadScheduledExecutor();private ScheduledFuture<?> pending;
    @Override public void onCreate(Bundle b){super.onCreate(b);notebook=Notebook.load(this);show();}
    private Button button(String text,LinearLayout box,Runnable r){Button b=new Button(this);b.setText(text);b.setTextSize(12);box.addView(b);b.setOnClickListener(v->r.run());return b;}
    private void persist(){if(pending!=null)pending.cancel(false);pending=disk.schedule(()->{try{notebook.save(this);}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Save failed: "+e.getMessage(),Toast.LENGTH_LONG).show());}},600,TimeUnit.MILLISECONDS);}
    private void show(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xffe7eae9);setContentView(root);toolbar=new LinearLayout(this);toolbar.setOrientation(LinearLayout.HORIZONTAL);HorizontalScrollView strip=new HorizontalScrollView(this);strip.addView(toolbar);root.addView(strip);button("InkProof",toolbar,()->{});button("SERVER",toolbar,()->input("Backend URL (tablet: http://YOUR_PC_IP:8080)",getPreferences(0).getString("server","http://10.0.2.2:8080"),s->{getPreferences(0).edit().putString("server",s.replaceAll("/$","")).apply();checkHealth();}));button("AI STATUS",toolbar,this::checkHealth);button("+ PAGE",toolbar,()->{notebook.addPage();persist();show();});button("PEN",toolbar,()->setTool("pen"));button("MARKER",toolbar,()->setTool("marker"));button("ERASER",toolbar,()->setTool("eraser"));button("COLOR",toolbar,this::chooseColor);button("WIDTH",toolbar,()->{width=width==3?6:width==6?10:3;Toast.makeText(this,"Width "+width,0).show();sync();});button("SMOOTH",toolbar,()->{stabilization=(stabilization+1)%4;Toast.makeText(this,"Stabilization "+new String[]{"Off","Low","Medium","High"}[stabilization],0).show();sync();});button("UNDO",toolbar,()->{if(selected!=null)selected.undo();});button("REDO",toolbar,()->{if(selected!=null)selected.redo();});
      ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));pages=new LinearLayout(this);pages.setOrientation(1);pages.setPadding(20,8,20,20);scroll.addView(pages);for(Notebook.Page p:notebook.pages)addPage(p);}
    private void setTool(String s){tool=s;sync();}private void sync(){if(selected!=null){selected.tool=tool;selected.color=color;selected.width=width;selected.stabilization=stabilization;}}
    private void addPage(Notebook.Page p){LinearLayout container=new LinearLayout(this);container.setOrientation(1);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,8,0,24);pages.addView(container,cp);LinearLayout actions=new LinearLayout(this);HorizontalScrollView bar=new HorizontalScrollView(this);bar.addView(actions);container.addView(bar);button(p.title,actions,()->input("Rename page",p.title,s->{p.title=s;persist();show();}));button("+ QUESTION",actions,()->input("Type question", "",s->{if(s.trim().isEmpty())return;Notebook.Question q=new Notebook.Question();q.prompt=s;p.questions.add(q);persist();show();}));button("PAPER",actions,()->{int[] colors={Color.WHITE,0xfffff9e9,0xffdedede,Color.BLACK,0xff202226,0xff383b40,0xff343c4c};String[] names={"White","Warm white","Grey","Black","Near black","Dark grey","Slate"};new AlertDialog.Builder(this).setItems(names,(d,i)->{p.background=colors[i];persist();show();}).show();});button("DELETE",actions,()->new AlertDialog.Builder(this).setMessage("Delete "+p.title+"?").setPositiveButton("Delete",(d,w)->{notebook.pages.remove(p);if(notebook.pages.isEmpty())notebook.addPage();persist();show();}).setNegativeButton("Cancel",null).show());
      InkView free=canvas(p,null,460);container.addView(free);for(Notebook.Question q:p.questions){LinearLayout header=new LinearLayout(this);header.setOrientation(1);header.setPadding(12,12,12,8);header.setBackgroundColor(0xffdce5e2);container.addView(header);button("QUESTION: "+q.prompt,header,()->input("Edit question",q.prompt,s->{q.prompt=s;persist();show();}));LinearLayout row=new LinearLayout(this);header.addView(row);button("CHECK MY WORK",row,()->analyze(p,q,"check"));button("SOLVE",row,()->analyze(p,q,"solve"));button("REMOVE",row,()->{p.questions.remove(q);persist();show();});TextView caption=new TextView(this);caption.setText("YOUR SOLUTION  ·  write with stylus");header.addView(caption);container.addView(canvas(p,q,320));}}
    private InkView canvas(Notebook.Page p,Notebook.Question q,int height){InkView v=new InkView(this,p,q,this::persist);v.setMinimumHeight(dp(height));v.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(height)));v.setOnClickListener(w->select(v));v.setOnFocusChangeListener((w,has)->{if(has)select(v);});v.setFocusableInTouchMode(true);v.setOnTouchListener((w,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN&&e.getToolType(0)==MotionEvent.TOOL_TYPE_STYLUS)select(v);return false;});return v;}
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
    private void select(InkView v){selected=v;sync();}
    private interface TextDone{void done(String text);}private void input(String title,String value,TextDone done){EditText edit=new EditText(this);edit.setText(value);new AlertDialog.Builder(this).setTitle(title).setView(edit).setPositiveButton("Save",(d,w)->done.done(edit.getText().toString())).setNegativeButton("Cancel",null).show();}
    private void chooseColor(){String[] names={"Black","White","Grey","Dark grey","Red","Orange","Yellow","Green","Cyan","Light blue","Blue","Purple","Pink"};int[] colors={0xff182433,-1,0xff999999,0xff444444,0xffe5484d,0xffff8a30,0xffffd640,0xff36a567,0xff00bfc6,0xff74baff,0xff3371df,0xff9459cc,0xffec76ac};new AlertDialog.Builder(this).setItems(names,(d,i)->{color=colors[i];sync();}).show();}
    private String readResponse(InputStream in) throws IOException {try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[4096];int count;while((count=stream.read(bytes))!=-1)out.write(bytes,0,count);return out.toString("UTF-8");}}
    private void checkHealth(){new Thread(()->{String status;try{HttpURLConnection c=(HttpURLConnection)new URL(getPreferences(0).getString("server","http://10.0.2.2:8080")+"/health").openConnection();c.setConnectTimeout(3000);c.setReadTimeout(3000);org.json.JSONObject j=new org.json.JSONObject(readResponse(c.getInputStream()));String value=j.optString("status");status=value.equals("configured")?"AI CONNECTED (backend configured; live request not yet verified)":value.equals("mock")?"MOCK MODE — no real AI":"AI NOT CONFIGURED";}catch(Exception e){status="BACKEND UNAVAILABLE";}String result=status;runOnUiThread(()->new AlertDialog.Builder(this).setMessage(result).setPositiveButton("OK",null).show());}).start();}
    private void analyze(Notebook.Page p,Notebook.Question q,String action){if(q.prompt.trim().isEmpty()||(action.equals("check")&&q.solution.isEmpty())){new AlertDialog.Builder(this).setMessage(action.equals("check")?"Write a solution before checking.":"Enter a question first.").setPositiveButton("OK",null).show();return;}Toast.makeText(this,"Contacting backend…",0).show();new Thread(()->{String result;try{URL url=new URL(getPreferences(0).getString("server","http://10.0.2.2:8080")+"/"+action);HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");org.json.JSONObject body=new org.json.JSONObject();body.put("pageId",p.id);body.put("questionId",q.id);body.put("question",q.prompt);org.json.JSONArray strokes=new org.json.JSONArray();for(Notebook.Stroke s:q.solution)strokes.put(s.json());body.put("solution",strokes);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}InputStream in=(c.getResponseCode()<400?c.getInputStream():c.getErrorStream());ByteArrayOutputStream buf=new ByteArrayOutputStream();byte[] chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1)buf.write(chunk,0,n);result=new org.json.JSONObject(buf.toString("UTF-8")).optString("message","No result");}catch(Exception e){result="BACKEND UNAVAILABLE: " +e.getMessage();}String message=result;runOnUiThread(()->new AlertDialog.Builder(this).setTitle(action.equals("check")?"CHECK MY WORK":"SOLVE").setMessage(message).setPositiveButton("Close",null).show());}).start();}
    @Override protected void onPause(){super.onPause();disk.execute(()->{try{notebook.save(this);}catch(Exception ignored){}});}
}
